package com.gphelper;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("gphelper")
public interface GPHelperConfig extends Config {

    enum OverlayPosition {
        TOP_LEFT("Arriba izquierda"),
        TOP_RIGHT("Arriba derecha"),
        TOP_CENTER("Arriba centro"),
        BOTTOM_LEFT("Abajo izquierda"),
        BOTTOM_RIGHT("Abajo derecha");

        private final String label;

        OverlayPosition(String label) {
            this.label = label;
        }

        @Override
        public String toString() {
            return label;
        }
    }

    @ConfigSection(
            name = "Overlay",
            description = "Ajustes del panel informativo en el juego",
            position = 0
    )
    String overlaySection = "overlay";

    @ConfigItem(
            keyName = "showOverlay",
            name = "Mostrar overlay",
            description = "Muestra el panel informativo dentro del juego",
            position = 1,
            section = overlaySection
    )
    default boolean showOverlay() {
        return true;
    }

    @ConfigItem(
            keyName = "overlayPosition",
            name = "Posición del overlay",
            description = "Esquina de la pantalla donde se dibuja el panel",
            position = 2,
            section = overlaySection
    )
    default OverlayPosition overlayPosition() {
        return OverlayPosition.TOP_LEFT;
    }

    @ConfigItem(
            keyName = "showXp",
            name = "Mostrar XP/h",
            description = "Incluye las líneas de XP en el overlay",
            position = 3,
            section = overlaySection
    )
    default boolean showXp() {
        return true;
    }

    @ConfigItem(
            keyName = "notifyMilestone",
            name = "Notificar cada (GP)",
            description = "Cada cuántos GP de ganancia neta se envía una notificación. 0 = desactivado",
            position = 4,
            section = overlaySection
    )
    default int notifyMilestone() {
        return 1_000_000;
    }

    @ConfigItem(
            keyName = "rareDropNotify",
            name = "Notificar drop raro (GP)",
            description = "GP mínimo de un solo drop para notificarlo. 0 = desactivado",
            position = 5,
            section = overlaySection
    )
    default int rareDropNotify() {
        return 500_000;
    }
}

package com.gphelper;

import com.google.inject.Provides;
import com.gphelper.overlay.GPHelperOverlay;
import com.gphelper.panel.GPHelperPanel;
import com.gphelper.service.GePriceService;
import com.gphelper.service.LootTracker;
import com.gphelper.service.SessionTracker;
import com.gphelper.service.XpTracker;
import com.gphelper.util.Format;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatCommandManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.time.LocalDate;

/**
 * GP Helper - Asistente de money making para Old School RuneScape.
 *
 * Herramienta 100% informativa: muestra datos del juego que RuneLite ya expone
 * (drops, XP, precios GE) y nada más. No automatiza clicks, no envía entrada
 * sintética y no incumple las reglas del juego.
 */
@Slf4j
@Singleton
@PluginDescriptor(
        name = "GP Helper",
        description = "Asistente de money making: profit tracker, precios del Grand Exchange y métodos de farming legales.",
        tags = {"gp", "money", "profit", "tracker", "ge", "prices", "farming"}
)
public class GPHelperPlugin extends Plugin {

    @Inject
    private Client client;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ConfigManager configManager;

    @Inject
    private ItemManager itemManager;

    @Inject
    private Notifier notifier;

    @Inject
    private ChatCommandManager chatCommandManager;

    @Inject
    private GPHelperConfig config;

    private SessionTracker sessionTracker;
    private XpTracker xpTracker;
    private LootTracker lootTracker;
    private GePriceService gePriceService;
    private GPHelperOverlay overlay;
    private GPHelperPanel panel;
    private NavigationButton navButton;

    private int tickCounter;
    private long lastPanelRefresh;

    @Provides
    GPHelperConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(GPHelperConfig.class);
    }

    @Override
    protected void startUp() {
        sessionTracker = new SessionTracker(notifier, config);
        xpTracker = new XpTracker(client);
        lootTracker = new LootTracker(itemManager, sessionTracker, notifier, config);
        gePriceService = new GePriceService(itemManager);

        overlay = new GPHelperOverlay(config, sessionTracker, xpTracker);
        if (config.showOverlay()) {
            overlayManager.add(overlay);
            applyOverlayPosition();
        }

        panel = new GPHelperPanel(sessionTracker, xpTracker, gePriceService, configManager);
        navButton = NavigationButton.builder()
                .tooltip("GP Helper")
                .icon(createIcon())
                .priority(8)
                .panel(panel)
                .build();
        clientToolbar.addNavigation(navButton);

        xpTracker.initIfNeeded();

        chatCommandManager.registerCommand("gp",
                (chatMessage, args) -> sendSessionSummary());
        chatCommandManager.registerCommand("gpreset",
                (chatMessage, args) -> {
                    sessionTracker.reset();
                    client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                            "GP Helper: sesión reiniciada.", null);
                });

        log.info("GP Helper iniciado");
    }

    @Override
    protected void shutDown() {
        overlayManager.remove(overlay);
        if (navButton != null) {
            clientToolbar.removeNavigation(navButton);
        }
        chatCommandManager.unregisterCommand("gp");
        chatCommandManager.unregisterCommand("gpreset");
        persistDailyTotals();
        log.info("GP Helper detenido");
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!"gphelper".equals(event.getGroup())) {
            return;
        }
        boolean show = config.showOverlay();
        boolean isAdded = overlayManager.anyMatch(o -> o == overlay);
        if (show && !isAdded) {
            overlayManager.add(overlay);
        } else if (!show && isAdded) {
            overlayManager.remove(overlay);
        }
        applyOverlayPosition();
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        xpTracker.onStatChanged(event);
        requestPanelRefresh();
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event) {
        lootTracker.addLoot(event.getItems());
        requestPanelRefresh();
    }

    @Subscribe
    public void onPlayerLootReceived(PlayerLootReceived event) {
        lootTracker.addLoot(event.getItems());
        requestPanelRefresh();
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        sessionTracker.tick();
        if (++tickCounter % 20 == 0) {
            requestPanelRefresh();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) {
            xpTracker.initIfNeeded();
        }
    }

    // ---------------------------------------------------------------- helpers

    private void sendSessionSummary() {
        String summary = "GP Helper | " + Format.gp(sessionTracker.netGp())
                + " (" + Format.gp(sessionTracker.gpPerHour()) + "/h)"
                + " | XP " + Format.number(xpTracker.totalGained())
                + " (" + Format.number(sessionTracker.xpPerHour(xpTracker.totalGained())) + "/h)"
                + " | " + Format.duration(sessionTracker.sessionSeconds());
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", summary, null);
    }

    private void requestPanelRefresh() {
        if (panel == null) {
            return;
        }
        long now = System.currentTimeMillis();
        if (now - lastPanelRefresh < 500) {
            return;
        }
        lastPanelRefresh = now;
        SwingUtilities.invokeLater(panel::refreshAll);
    }

    private void applyOverlayPosition() {
        if (overlay == null) {
            return;
        }
        switch (config.overlayPosition()) {
            case TOP_LEFT:
                overlay.setPosition(OverlayPosition.TOP_LEFT);
                break;
            case TOP_RIGHT:
                overlay.setPosition(OverlayPosition.TOP_RIGHT);
                break;
            case TOP_CENTER:
                overlay.setPosition(OverlayPosition.TOP_CENTER);
                break;
            case BOTTOM_LEFT:
                overlay.setPosition(OverlayPosition.BOTTOM_LEFT);
                break;
            case BOTTOM_RIGHT:
                overlay.setPosition(OverlayPosition.BOTTOM_RIGHT);
                break;
        }
    }

    private void persistDailyTotals() {
        LocalDate today = LocalDate.now();
        String gpKey = "daily.gp." + today;
        String xpKey = "daily.xp." + today;
        long gpToday = dailyTotal(gpKey) + Math.max(0, sessionTracker.netGp());
        long xpToday = dailyTotal(xpKey) + xpTracker.totalGained();
        configManager.setConfiguration("gphelper", gpKey, String.valueOf(gpToday));
        configManager.setConfiguration("gphelper", xpKey, String.valueOf(xpToday));
    }

    private long dailyTotal(String key) {
        String v = configManager.getConfiguration("gphelper", key);
        if (v == null || v.isEmpty()) {
            return 0;
        }
        try {
            return Long.parseLong(v);
        } catch (NumberFormatException e) {
            return 0;
        }
    }

    private BufferedImage createIcon() {
        BufferedImage img = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(255, 190, 0));
        g.fillOval(2, 2, 20, 20);
        g.setColor(new Color(130, 90, 0));
        g.drawOval(2, 2, 20, 20);
        g.setColor(new Color(90, 60, 0));
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 11));
        FontMetrics fm = g.getFontMetrics();
        String text = "$";
        int x = (24 - fm.stringWidth(text)) / 2;
        int y = (24 - fm.getHeight()) / 2 + fm.getAscent();
        g.drawString(text, x, y);
        g.dispose();
        return img;
    }
}

