package com.gphelper.overlay;

import com.gphelper.GPHelperConfig;
import com.gphelper.service.SessionTracker;
import com.gphelper.service.XpTracker;
import com.gphelper.util.Format;
import net.runelite.api.Skill;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import java.awt.Dimension;
import java.awt.Graphics2D;

/**
 * Panel informativo dibujado en el juego. Solo muestra datos; nunca genera clicks.
 */
public class GPHelperOverlay extends OverlayPanel {

    private final GPHelperConfig config;
    private final SessionTracker session;
    private final XpTracker xpTracker;

    public GPHelperOverlay(GPHelperConfig config, SessionTracker session, XpTracker xpTracker) {
        this.config = config;
        this.session = session;
        this.xpTracker = xpTracker;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(TitleComponent.builder().text("GP Helper").build());

        addLine("Sesión", Format.duration(session.sessionSeconds()));
        addLine("GP neto", Format.gp(session.netGp()));
        addLine("GP/h", Format.gp(session.gpPerHour()));

        if (config.showXp()) {
            addLine("XP total", Format.number(xpTracker.totalGained()));
            addLine("XP/h", Format.number(session.xpPerHour(xpTracker.totalGained())));
            addLine("Top XP", topXp());
        }

        addLine("Drops", Format.number(session.dropCount())
                + " · " + Format.gp(session.avgPerDrop()) + "/drop");

        return super.render(graphics);
    }

    private String topXp() {
        Skill s = xpTracker.topSkill();
        if (s == null) {
            return "-";
        }
        return s.getName() + " " + Format.number(xpTracker.gainedFor(s));
    }

    private void addLine(String left, String right) {
        panelComponent.getChildren().add(LineComponent.builder()
                .left(left)
                .right(right)
                .build());
    }
}

package com.gphelper.panel;

import com.gphelper.service.GePriceService;
import com.gphelper.service.SessionTracker;
import com.gphelper.service.XpTracker;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.PluginPanel;

import javax.swing.JTabbedPane;
import java.awt.BorderLayout;

/**
 * Side panel principal del plugin con tres pestañas: Profit, GE y Métodos.
 */
public class GPHelperPanel extends PluginPanel {

    private final ProfitPanel profitPanel;
    private final GePanel gePanel;

    public GPHelperPanel(SessionTracker session, XpTracker xpTracker,
                         GePriceService ge, ConfigManager configManager) {
        super();

        profitPanel = new ProfitPanel(session, xpTracker, configManager);
        gePanel = new GePanel(ge, configManager);

        JTabbedPane tabs = new JTabbedPane();
        tabs.addTab("Profit", profitPanel);
        tabs.addTab("GE", gePanel);
        tabs.addTab("Métodos", new MethodsPanel());

        setLayout(new BorderLayout());
        add(tabs, BorderLayout.CENTER);
    }

    public void refreshAll() {
        profitPanel.refresh();
        gePanel.refreshFavorites();
    }
}

package com.gphelper.panel;

import com.gphelper.service.GePriceService;
import com.gphelper.util.Format;
import net.runelite.api.ItemComposition;
import net.runelite.client.config.ConfigManager;
import net.runelite.http.api.item.ItemPrice;

import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.ListSelectionModel;
import javax.swing.DefaultListModel;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.util.ArrayList;
import java.util.List;

/**
 * Pestaña "GE": búsqueda de ítems, precios del Grand Exchange y favoritos.
 */
public class GePanel extends JPanel {

    private static final String FAV_KEY = "favItems";

    private final GePriceService ge;
    private final ConfigManager configManager;

    private final JTextField searchField = new JTextField();
    private final DefaultListModel<String> resultModel = new DefaultListModel<>();
    private final JList<String> resultList = new JList<>(resultModel);
    private final List<ItemPrice> results = new ArrayList<>();

    private final JTextArea detailArea = new JTextArea();

    private final DefaultListModel<String> favModel = new DefaultListModel<>();
    private final JList<String> favList = new JList<>(favModel);
    private final List<Integer> favorites = new ArrayList<>();

    public GePanel(GePriceService ge, ConfigManager configManager) {
        this.ge = ge;
        this.configManager = configManager;

        setLayout(new BorderLayout());
        setBorder(new EmptyBorder(8, 8, 8, 8));

        // Barra de búsqueda
        JButton searchButton = new JButton("Buscar");
        searchField.addActionListener(e -> doSearch());
        searchButton.addActionListener(e -> doSearch());
        JPanel top = new JPanel(new BorderLayout(4, 4));
        top.add(searchField, BorderLayout.CENTER);
        top.add(searchButton, BorderLayout.EAST);
        add(top, BorderLayout.NORTH);

        JPanel body = new JPanel();
        body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));

        JLabel resultsLabel = new JLabel("Resultados");
        resultsLabel.setForeground(Color.WHITE);
        resultsLabel.setFont(resultsLabel.getFont().deriveFont(Font.BOLD));
        resultsLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        resultList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        resultList.addListSelectionListener(e -> {
            if (!e.getValueIsAdjusting()) {
                showResultDetails();
            }
        });
        JScrollPane resultScroll = new JScrollPane(resultList);
        resultScroll.setAlignmentX(Component.LEFT_ALIGNMENT);
        resultScroll.setPreferredSize(new Dimension(0, 130));
        resultScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 130));

        detailArea.setEditable(false);
        detailArea.setLineWrap(true);
        detailArea.setWrapStyleWord(true);
        detailArea.setBorder(new EmptyBorder(6, 6, 6, 6));
        JScrollPane detailScroll = new JScrollPane(detailArea);
        detailScroll.setAlignmentX(Component.LEFT_ALIGNMENT);
        detailScroll.setPreferredSize(new Dimension(0, 110));
        detailScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 110));

        JButton refreshButton = new JButton("Actualizar precios");
        refreshButton.addActionListener(e -> refreshFavorites());
        JPanel favHeader = new JPanel(new BorderLayout());
        JLabel favTitle = new JLabel("Favoritos");
        favTitle.setForeground(Color.WHITE);
        favTitle.setFont(favTitle.getFont().deriveFont(Font.BOLD));
        favHeader.add(favTitle, BorderLayout.WEST);
        favHeader.add(refreshButton, BorderLayout.EAST);
        favHeader.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        favHeader.setAlignmentX(Component.LEFT_ALIGNMENT);

        favList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        JScrollPane favScroll = new JScrollPane(favList);
        favScroll.setAlignmentX(Component.LEFT_ALIGNMENT);
        favScroll.setPreferredSize(new Dimension(0, 130));
        favScroll.setMaximumSize(new Dimension(Integer.MAX_VALUE, 130));

        JButton addFavButton = new JButton("★ Añadir favorito");
        addFavButton.addActionListener(e -> addFavorite());
        JButton removeFavButton = new JButton("Quitar favorito");
        removeFavButton.addActionListener(e -> removeFavorite());
        JPanel favButtons = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        favButtons.add(addFavButton);
        favButtons.add(removeFavButton);
        favButtons.setAlignmentX(Component.LEFT_ALIGNMENT);
        favButtons.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));

        body.add(resultsLabel);
        body.add(Box.createVerticalStrut(4));
        body.add(resultScroll);
        body.add(Box.createVerticalStrut(4));
        body.add(detailScroll);
        body.add(Box.createVerticalStrut(6));
        body.add(favHeader);
        body.add(Box.createVerticalStrut(4));
        body.add(favScroll);
        body.add(Box.createVerticalStrut(4));
        body.add(favButtons);

        JLabel disclaimer = new JLabel("<html><i>Precios guía de la Wiki OSRS. Compra/venta instantánea son estimaciones.</i></html>");
        disclaimer.setForeground(Color.GRAY);
        disclaimer.setAlignmentX(Component.LEFT_ALIGNMENT);
        body.add(Box.createVerticalStrut(6));
        body.add(disclaimer);

        add(body, BorderLayout.CENTER);

        loadFavorites();
        refreshFavorites();
    }

    private void doSearch() {
        results.clear();
        resultModel.clear();
        List<ItemPrice> found = ge.search(searchField.getText());
        int shown = 0;
        for (ItemPrice p : found) {
            if (shown++ >= 50) {
                break;
            }
            results.add(p);
            resultModel.addElement(p.getName() + "   [id " + p.getId() + "]");
        }
        if (results.isEmpty()) {
            resultModel.addElement("Sin resultados");
        }
        detailArea.setText("");
    }

    private void showResultDetails() {
        int index = resultList.getSelectedIndex();
        if (index < 0 || index >= results.size()) {
            return;
        }
        ItemPrice p = results.get(index);
        ItemComposition comp = ge.composition(p.getId());
        int price = Math.max(0, p.getPrice());
        long buy = GePriceService.estimateBuy(price);
        long sell = GePriceService.estimateSell(price);
        int ha = comp == null ? 0 : Math.max(0, comp.getHaPrice());

        detailArea.setText(
                "Nombre: " + p.getName() + "\n" +
                "GE (guía): " + Format.number(price) + "\n" +
                "Compra (aprox): " + Format.number(buy) + "\n" +
                "Venta (aprox): " + Format.number(sell) + "\n" +
                "Alquimia (HA): " + Format.number(ha) + "\n" +
                "Margen alch: " + Format.number(ha - price));
    }

    private void addFavorite() {
        int index = resultList.getSelectedIndex();
        if (index < 0 || index >= results.size()) {
            return;
        }
        int id = results.get(index).getId();
        if (!favorites.contains(id)) {
            favorites.add(id);
            persistFavorites();
            refreshFavorites();
        }
    }

    private void removeFavorite() {
        int index = favList.getSelectedIndex();
        if (index < 0 || index >= favorites.size()) {
            return;
        }
        favorites.remove(index);
        persistFavorites();
        refreshFavorites();
    }

    public void refreshFavorites() {
        favModel.clear();
        if (favorites.isEmpty()) {
            favModel.addElement("Sin favoritos");
            return;
        }
        for (Integer id : favorites) {
            long price = Math.max(0, ge.guidePrice(id));
            favModel.addElement(ge.name(id) + " — " + Format.gp(price));
        }
    }

    private void loadFavorites() {
        String raw = configManager.getConfiguration("gphelper", FAV_KEY);
        favorites.clear();
        if (raw == null || raw.isEmpty()) {
            return;
        }
        for (String part : raw.split(",")) {
            try {
                favorites.add(Integer.parseInt(part.trim()));
            } catch (NumberFormatException ignored) {
                // ignorar entradas inválidas
            }
        }
    }

    private void persistFavorites() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < favorites.size(); i++) {
            if (i > 0) {
                sb.append(',');
            }
            sb.append(favorites.get(i));
        }
        configManager.setConfiguration("gphelper", FAV_KEY, sb.toString());
    }
}

