import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.time.LocalDate;

/**
 * Pestaña "Profit": resumen de la sesión y ajustes manuales de GP.
 */
public class ProfitPanel extends JPanel {

    private static final String DAILY_GP_PREFIX = "daily.gp.";
    private static final String DAILY_XP_PREFIX = "daily.xp.";

    private final SessionTracker session;
    private final XpTracker xpTracker;
    private final ConfigManager configManager;

    private final JLabel sessionLabel = new JLabel();
    private final JLabel netLabel = new JLabel();
    private final JLabel gphLabel = new JLabel();
    private final JLabel xpLabel = new JLabel();
    private final JLabel xphLabel = new JLabel();
    private final JLabel dropsLabel = new JLabel();
    private final JLabel avgLabel = new JLabel();
    private final JLabel todayLabel = new JLabel();
    private final JTextField customField = new JTextField("0");

    public ProfitPanel(SessionTracker session, XpTracker xpTracker, ConfigManager configManager) {
        this.session = session;
        this.xpTracker = xpTracker;
        this.configManager = configManager;

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(new EmptyBorder(8, 8, 8, 8));

        addTitle("Sesión actual");
        addRow("Tiempo:", sessionLabel);
        addRow("GP neto:", netLabel);
        addRow("GP/hora:", gphLabel);
        addRow("XP ganada:", xpLabel);
        addRow("XP/hora:", xphLabel);
        addRow("Drops:", dropsLabel);
        addRow("Promedio/drop:", avgLabel);
        addRow("Hoy (GP):", todayLabel);

        add(Box.createVerticalStrut(10));

        JButton reset = new JButton("Reiniciar sesión");
        reset.addActionListener(e -> {
            int result = JOptionPane.showConfirmDialog(
                    this, "¿Reiniciar la sesión actual?", "GP Helper",
                    JOptionPane.OK_CANCEL_OPTION);
            if (result == JOptionPane.OK_OPTION) {
                session.reset();
                refresh();
            }
        });
        reset.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(reset);

        add(Box.createVerticalStrut(6));

        JPanel quick = new JPanel(new GridLayout(2, 2, 4, 4));
        quick.add(btn("+1K", 1_000));
        quick.add(btn("-1K", -1_000));
        quick.add(btn("+10K", 10_000));
        quick.add(btn("+100K", 100_000));
        quick.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(quick);

        add(Box.createVerticalStrut(6));

        JPanel custom = new JPanel(new BorderLayout(4, 4));
        custom.add(new JLabel("Cantidad:"), BorderLayout.WEST);
        JButton apply = new JButton("Aplicar");
        apply.addActionListener(e -> applyCustom());
        customField.addActionListener(e -> applyCustom());
        custom.add(customField, BorderLayout.CENTER);
        custom.add(apply, BorderLayout.EAST);
        custom.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(custom);

        JLabel hint = new JLabel("Ajustes para ventas/gastos no detectados");
        hint.setForeground(Color.GRAY);
        hint.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(Box.createVerticalStrut(8));
        add(hint);

        refresh();
    }

    private JButton btn(String text, int delta) {
        JButton b = new JButton(text);
        b.addActionListener(e -> {
            session.adjust(delta);
            refresh();
        });
        return b;
    }

    private void applyCustom() {
        try {
            long value = Long.parseLong(customField.getText().trim());
            session.adjust(value);
            customField.setText("0");
            refresh();
        } catch (NumberFormatException ex) {
            customField.setText("0");
        }
    }

    public void refresh() {
        sessionLabel.setText(Format.duration(session.sessionSeconds()));
        netLabel.setText(Format.gp(session.netGp()));
        gphLabel.setText(Format.gp(session.gpPerHour()));
        xpLabel.setText(Format.number(xpTracker.totalGained()));
        xphLabel.setText(Format.number(session.xpPerHour(xpTracker.totalGained())));
        dropsLabel.setText(Format.number(session.dropCount()));
        avgLabel.setText(Format.gp(session.avgPerDrop()));
        todayLabel.setText(Format.gp(dailyTotal(DAILY_GP_PREFIX + LocalDate.now())));
    }

    private long dailyTotal(String key) {
        String v = configManager.getConfiguration("gphelper", key);
        if (v == null || v.isEmpty()) {
            return 0;
        }
        try {
            return Long.parseLong(v);
        } catch (NumberFormatException e) {
            return 0;
        }
    }

    private void addTitle(String title) {
        JLabel label = new JLabel(title);
        label.setFont(label.getFont().deriveFont(Font.BOLD));
        label.setForeground(Color.WHITE);
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(label);
        add(Box.createVerticalStrut(4));
    }

    private void addRow(String labelText, JLabel value) {
        JPanel row = new JPanel(new BorderLayout());
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
        JLabel label = new JLabel(labelText);
        label.setForeground(Color.LIGHT_GRAY);
        value.setForeground(Color.WHITE);
        row.add(label, BorderLayout.WEST);
        row.add(value, BorderLayout.EAST);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(row);
    }
}

package com.gphelper.service;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;

import java.util.List;

/**
 * Acceso a precios del Grand Exchange a través del ItemManager de RuneLite
 * (que a su vez usa la API de la Wiki OSRS). Sin llamadas HTTP propias.
 */
@Slf4j
public class GePriceService {

    private final ItemManager itemManager;

    public GePriceService(ItemManager itemManager) {
        this.itemManager = itemManager;
    }

    public List<ItemPrice> search(String query) {
        String q = query == null ? "" : query.trim();
        if (q.isEmpty()) {
            return List.of();
        }
        List<ItemPrice> result = itemManager.search(q);
        return result == null ? List.of() : result;
    }

    public int guidePrice(int id) {
        return itemManager.getItemPrice(id);
    }

    public ItemComposition composition(int id) {
        return itemManager.getItemComposition(id);
    }

    public String name(int id) {
        ItemComposition c = composition(id);
        return c == null ? ("Item " + id) : c.getName();
    }

    /** Estimación de precio de compra instantánea (aproximada, no oficial). */
    public static long estimateBuy(long guide) {
        return (long) Math.ceil(guide * 1.06 / 10.0) * 10;
    }

    /** Estimación de precio de venta instantánea (aproximada, no oficial). */
    public static long estimateSell(long guide) {
        return (long) Math.floor(guide * 0.94 / 10.0) * 10;
    }
}

package com.gphelper.service;

import com.gphelper.GPHelperConfig;
import com.gphelper.util.Format;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.Notifier;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

import java.util.Collection;

/**
 * Convierte los eventos de loot (drops de npc y de jugadores) en GP mediante
 * los precios guía de RuneLite. Solo lectura de eventos; no automatiza nada.
 */
@Slf4j
public class LootTracker {

    private final ItemManager itemManager;
    private final SessionTracker session;
    private final Notifier notifier;
    private final GPHelperConfig config;

    public LootTracker(ItemManager itemManager, SessionTracker session,
                       Notifier notifier, GPHelperConfig config) {
        this.itemManager = itemManager;
        this.session = session;
        this.notifier = notifier;
        this.config = config;
    }

    public void addLoot(Collection<ItemStack> items) {
        long value = 0;
        for (ItemStack stack : items) {
            if (stack == null || stack.getId() <= 0) {
                continue;
            }
            value += (long) itemManager.getItemPrice(stack.getId()) * Math.max(1, stack.getQuantity());
        }
        if (value <= 0) {
            return;
        }
        session.addLoot(value);

        int rareThreshold = config.rareDropNotify();
        if (rareThreshold > 0 && value >= rareThreshold) {
            notifier.notify("💎 GP Helper: drop raro de " + Format.gp(value) + " GP");
        }
    }
}

package com.gphelper.service;

import com.gphelper.GPHelperConfig;
import com.gphelper.util.Format;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.Notifier;

/**
 * Contador de la sesión actual: GP ganado/gastado, drops, tiempo y tasas por hora.
 */
@Slf4j
public class SessionTracker {

    private final Notifier notifier;
    private final GPHelperConfig config;

    private volatile long startMillis = System.currentTimeMillis();
    private volatile long earnedGp;
    private volatile long spentGp;
    private volatile long dropCount;
    private volatile long ticks;
    private volatile long lastMilestoneFloor;

    public SessionTracker(Notifier notifier, GPHelperConfig config) {
        this.notifier = notifier;
        this.config = config;
    }

    public synchronized void addLoot(long value) {
        earnedGp += value;
        dropCount++;
        checkMilestones();
    }

    public synchronized void addExpense(long value) {
        spentGp += value;
    }

    /** Ajuste manual (ventas o gastos no detectados automáticamente). */
    public synchronized void adjust(long delta) {
        if (delta >= 0) {
            earnedGp += delta;
        } else {
            spentGp += -delta;
        }
        checkMilestones();
    }

    public synchronized void tick() {
        ticks++;
    }

    public synchronized void reset() {
        startMillis = System.currentTimeMillis();
        earnedGp = 0;
        spentGp = 0;
        dropCount = 0;
        ticks = 0;
        lastMilestoneFloor = 0;
        log.info("GP Helper: sesión reiniciada");
    }

    private void checkMilestones() {
        int milestone = config.notifyMilestone();
        long net = earnedGp - spentGp;
        if (milestone <= 0 || net <= 0) {
            return;
        }
        long floor = net / milestone;
        if (floor > lastMilestoneFloor) {
            lastMilestoneFloor = floor;
            notifier.notify("💰 GP Helper: alcanzaste " + Format.gp(net) + " GP en la sesión");
        }
    }

    public long netGp() {
        return earnedGp - spentGp;
    }

    public long earnedGp() {
        return earnedGp;
    }

    public long spentGp() {
        return spentGp;
    }

    public long dropCount() {
        return dropCount;
    }

    public long ticks() {
        return ticks;
    }

    public long sessionSeconds() {
        return Math.max(0, (System.currentTimeMillis() - startMillis) / 1000L);
    }

    public double hoursElapsed() {
        return (System.currentTimeMillis() - startMillis) / 3_600_000.0;
    }

    public long gpPerHour() {
        double h = hoursElapsed();
        return h > 0.0001 ? (long) (netGp() / h) : 0;
    }

    public long xpPerHour(long xp) {
        double h = hoursElapsed();
        return h > 0.0001 ? (long) (xp / h) : 0;
    }

    public long avgPerDrop() {
        return dropCount == 0 ? 0 : Math.max(0, earnedGp) / dropCount;
    }
}

package com.gphelper.service;

import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;

import java.util.EnumMap;
import java.util.Map;

/**
 * Rastrea la XP ganada en la sesión por skill.
 * Solo lee eventos de XP que el propio RuneLite ya expone; no automatiza nada.
 */
public class XpTracker {

    private final Client client;
    private final Map<Skill, Integer> snapshot = new EnumMap<>(Skill.class);
    private final Map<Skill, Integer> gained = new EnumMap<>(Skill.class);
    private volatile boolean initialized;

    public XpTracker(Client client) {
        this.client = client;
    }

    public synchronized void initIfNeeded() {
        if (initialized) {
            return;
        }
        for (Skill s : Skill.values()) {
            snapshot.put(s, client.getSkillExperience(s));
        }
        initialized = true;
    }

    public synchronized void onStatChanged(StatChanged event) {
        initIfNeeded();
        Skill skill = event.getSkill();
        int now = event.getXp();
        int prev = snapshot.getOrDefault(skill, now);
        int diff = now - prev;
        snapshot.put(skill, now);
        if (diff > 0) {
            gained.merge(skill, diff, Integer::sum);
        }
    }

    public synchronized int totalGained() {
        int total = 0;
        for (int v : gained.values()) {
            total += v;
        }
        return total;
    }

    public synchronized Skill topSkill() {
        Skill best = null;
        int bestXp = 0;
        for (Map.Entry<Skill, Integer> e : gained.entrySet()) {
            if (e.getValue() > bestXp) {
                bestXp = e.getValue();
                best = e.getKey();
            }
        }
        return best;
    }

    public synchronized int gainedFor(Skill skill) {
        return gained.getOrDefault(skill, 0);
    }
}

package com.gphelper.util;

public final class Format {

    private Format() {
    }

    /** Da formato corto a un valor de GP: 1,23M / 456K / 900 */
    public static String gp(long value) {
        boolean negative = value < 0;
        long abs = Math.abs(value);
        String out;
        if (abs >= 1_000_000_000L) {
            out = String.format("%.2fB", abs / 1_000_000_000.0);
        } else if (abs >= 1_000_000L) {
            out = String.format("%.2fM", abs / 1_000_000.0);
        } else if (abs >= 1_000L) {
            out = String.format("%.1fK", abs / 1_000.0);
        } else {
            out = String.valueOf(abs);
        }
        return (negative ? "-" : "") + out;
    }

    /** Número con separadores de miles: 1,234,567 */
    public static String number(long value) {
        return String.format("%,d", value);
    }

    /** Duración en HH:MM:SS a partir de segundos */
    public static String duration(long totalSeconds) {
        if (totalSeconds < 0) {
            totalSeconds = 0;
        }
        long h = totalSeconds / 3600;
        long m = (totalSeconds % 3600) / 60;
        long s = totalSeconds % 60;
        return String.format("%02d:%02d:%02d", h, m, s);
    }
}
